def rasterize(polys, w, h, ox, oy, scale, ss=4):
    """Rasterise polygons into a w*h coverage buffer (bytearray, 0..255).

    Font space is y-up. Pixel position of font origin = (ox, oy).
    scale = font units per pixel.
    """
    # bucket edges by yf range for speed
    edges = []
    for poly in polys:
        m = len(poly)
        for i in range(m):
            ax, ay = poly[i]
            bx, by = poly[(i + 1) % m]
            if ay != by:
                if ay < by:
                    edges.append((ay, by, ax, (bx - ax) / (by - ay)))
                else:
                    edges.append((by, ay, bx, (ax - bx) / (ay - by)))
    edges.sort()
    cov = [0] * (w * h)
    inv = 1.0 / scale
    ei = 0
    ne = len(edges)
    act = []
    for py in range(h):
        for ssy in range(ss):
            ysamp = py + (ssy + 0.5) / ss
            yf = (oy - ysamp) * scale
            while ei < ne and edges[ei][0] <= yf:
                act.append(edges[ei])
                ei += 1
            xs = []
            keep = []
            for e in act:
                if e[1] > yf:
                    keep.append(e)
                    if e[0] <= yf:
                        xs.append(e[2] + (yf - e[0]) * e[3])
            act = keep
            if len(xs) < 2:
                continue
            xs.sort()
            row = py * w
            for i in range(0, len(xs) - 1, 2):
                pa = xs[i] / scale + ox
                pb = xs[i + 1] / scale + ox
                for x in range(max(0, int(pa)), min(w, int(pb) + 1)):
                    cov[row + x] += 1
    out = bytearray(w * h)
    for i, c in enumerate(cov):
        if c:
            out[i] = 255 if c >= ss else (255 * c) // ss
    return out

